  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = vatSummary([issued1, undefined, null]);

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].vat, 1995);
});

test('vatSummary with multiple invoices across different rates', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }], // 21%
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-06',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }], // 21%
  }).value;
  const issued2 = issueInvoice(inv2, []).value;

  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 50 }], // 9%
  }).value;
  const issued3 = issueInvoice(inv3, []).value;

  const result = vatSummary([issued1, issued2, issued3]);

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
  // 21%: 9500 + 19000 = 28500, VAT = 1995 + 3990 = 5985
  assert.equal(result.value[0].rate, 21);
  assert.equal(result.value[0].base, 28500);
  assert.equal(result.value[0].vat, 5985);
  // 9%: 2500, VAT = 225
  assert.equal(result.value[1].rate, 9);
  assert.equal(result.value[1].base, 2500);
  assert.equal(result.value[1].vat, 225);
});

test('vatSummary with combined line and tier discounts', () => {
  // C-001 is gold with 5% tier discount
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 10 }], // 10% explicit discount
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = vatSummary([issued1]);

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  // Explicit discount wins: 9500 - 950 (10%) = 8550
  // VAT: 21% of 8550 = 1795.5 → 1796
  assert.equal(result.value[0].base, 8550);
  assert.equal(result.value[0].vat, 1796);
});

test('vatSummary with large amounts', () => {
  const inv1 = {
    status: 'issued',
    number: 'INV-2026-0001',
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [
      {
        sku: 'BIG',
        name: 'Big Item',
        qty: 100,
        unitPrice: 100000, // 10000 euros
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = vatSummary([inv1]);

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].base, 10000000); // 100 * 100000
  assert.equal(result.value[0].vat, 2100000); // 21% of 10000000
});
